func (siw *ServerInterfaceWrapper) SearchCatalog(w http.ResponseWriter, r *http.Request) {

	var err error
	_ = err

	// Parameter object where we will unmarshal all parameters from the context
	var params SearchCatalogParams

	// ------------- Required query parameter "type" -------------

	err = runtime.BindQueryParameterWithOptions("form", true, true, "type", r.URL.Query(), &params.Type, runtime.BindQueryParameterOptions{Type: "string", Format: ""})
	if err != nil {
		var requiredError *runtime.RequiredParameterError
		if errors.As(err, &requiredError) {
			siw.ErrorHandlerFunc(w, r, &RequiredParamError{ParamName: "type"})
		} else {
			siw.ErrorHandlerFunc(w, r, &InvalidParamFormatError{ParamName: "type", Err: err})
		}
		return
	}

	// ------------- Required query parameter "q" -------------

	err = runtime.BindQueryParameterWithOptions("form", true, true, "q", r.URL.Query(), &params.Q, runtime.BindQueryParameterOptions{Type: "string", Format: ""})
	if err != nil {
		var requiredError *runtime.RequiredParameterError
		if errors.As(err, &requiredError) {
			siw.ErrorHandlerFunc(w, r, &RequiredParamError{ParamName: "q"})
		} else {
			siw.ErrorHandlerFunc(w, r, &InvalidParamFormatError{ParamName: "q", Err: err})
		}
		return
	}

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.SearchCatalog(w, r, params)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

type UnescapedCookieParamError struct {
	ParamName string
	Err       error
}

func (e *UnescapedCookieParamError) Error() string {
	return fmt.Sprintf("error unescaping cookie parameter '%s'", e.ParamName)
}

func (e *UnescapedCookieParamError) Unwrap() error {
	return e.Err
}

type UnmarshalingParamError struct {
	ParamName string
	Err       error
}

func (e *UnmarshalingParamError) Error() string {
	return fmt.Sprintf("Error unmarshaling parameter %s as JSON: %s", e.ParamName, e.Err.Error())
}

func (e *UnmarshalingParamError) Unwrap() error {
	return e.Err
}

type RequiredParamError struct {
	ParamName string
}

func (e *RequiredParamError) Error() string {
	return fmt.Sprintf("Query argument %s is required, but not found", e.ParamName)
}

type RequiredHeaderError struct {
	ParamName string
	Err       error
}

func (e *RequiredHeaderError) Error() string {
	return fmt.Sprintf("Header parameter %s is required, but not found", e.ParamName)
}

func (e *RequiredHeaderError) Unwrap() error {
	return e.Err
}

type InvalidParamFormatError struct {
	ParamName string
	Err       error
}

func (e *InvalidParamFormatError) Error() string {
	return fmt.Sprintf("Invalid format for parameter %s: %s", e.ParamName, e.Err.Error())
}

func (e *InvalidParamFormatError) Unwrap() error {
	return e.Err
}

type TooManyValuesForParamError struct {
	ParamName string
	Count     int
}

func (e *TooManyValuesForParamError) Error() string {
	return fmt.Sprintf("Expected one value for %s, got %d", e.ParamName, e.Count)
}

// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/search", wrapper.SearchCatalog)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/products/resolve", wrapper.ResolveProduct)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/products/{productId}", wrapper.GetProduct)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/products/prices:batch", wrapper.BatchPrices)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/products/price-history:batch", wrapper.BatchPriceHistory)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/recommendations:score", wrapper.ScoreRecommendations)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/fx/latest", wrapper.GetFxLatest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/platforms", wrapper.ListPlatforms)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/refresh", wrapper.TriggerRefresh)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/internal/refresh", wrapper.InternalRefresh)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/internal/normalize-community-regions", wrapper.InternalNormalizeCommunityRegions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/products", wrapper.CreateCommunityProduct)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/admin/products/{productId}/pricecharting", wrapper.SetProductMapping)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/products/{productId}/promote", wrapper.PromoteProduct)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/products/promote-candidates", wrapper.ListPromoteCandidates)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/products/{productId}/promote-candidates/dismiss", wrapper.DismissPromoteCandidate)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/admin/products/{productId}", wrapper.DeleteProduct)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/products/unmatched", wrapper.ListUnmatchedProducts)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/products/community", wrapper.ListCommunityProducts)

	return m
}

